    public Shape(String color) {
        this.color = color;
    }

    public double area() {
        return 0; // Placeholder for area calculation
    }

    public void display() {
        System.out.println("Shape with color: " + color);
    }
}

class Circle extends Shape {
    double radius;

    public Circle(String color, double radius) {
        super(color); // Call the constructor of the parent class
        this.radius = radius;
    }

    @Override
    public double area() {
        return Math.PI * radius * radius;
    }
