import math

def is_prime(number):
    if not isinstance(number, int):
        return False
    if number <= 1:
        return False
    if number == 2:
        return True
    if number > 2 and number % 2 == 0:
        return False

    for i in range(3, int(math.sqrt(number)) + 1, 2):
        if number % i == 0:
            return False
    return True

